        digits = [list(item) for item in
                  itertools.product(STATES, repeat=len(union))]
        maps = []
        for fi in involved:
            scope = scopes[fi]
            fstr = [3 ** (len(scope) - 1 - i) for i in range(len(scope))]
            where = [union.index(x) for x in scope]
            table = []
